const cwd = '<test>';
const p = n => cwd + '\\' + n;
const out = {};
const tryit = async (k, f) => { try { out[k] = await f(); } catch (e) { out[k] = {threw: String(e?.message ?? e)}; } };
const list = tools.list();
await tryit('Read', () => Read({file_path: p('notes.txt')}));
await tryit('Glob', () => Glob({pattern: 'sub/*', path: cwd}));
await tryit('Write', () => Write({file_path: p('written.txt'), content: 'hi\n'}));
await tryit('Edit', () => Edit({file_path: p('written.txt'), old_string: 'hi', new_string: 'hello'}));
const shellName = list.includes('PowerShell') ? 'PowerShell' : 'Bash';
await tryit('shell_' + shellName, () => globalThis[shellName]({command: 'echo globals', description: 'Echo a test string'}));
const toolish = Object.getOwnPropertyNames(globalThis).filter(n => /^[A-Z]/.test(n) && typeof globalThis[n] === 'function' && list.includes(n));
({out, list, toolish});

